const fs = require('fs'), path = require('path');
function walk(d, o = []) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    if (e.name === 'obj' || e.name === 'bin') continue;
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p, o); else if (p.endsWith('.cs')) o.push(p);
  }
  return o;
}
const res = [];
for (const f of walk(process.argv[2])) {
  const L = fs.readFileSync(f, 'utf8').split('\n');
  for (let i = 0; i < L.length; i++) {
    const l = L[i];
    if (!/^\s+(public|private|internal|protected)\b/.test(l)) continue;
    if (!l.includes('(')) continue;
    if (/\b(class|record|interface|enum|struct)\b/.test(l) && /;\s*$/.test(l)) continue;
    let j = i;
    while (j < L.length && !/[{;]|=>/.test(L[j])) j++;
    if (j >= L.length || !L[j].includes('{') || /=>/.test(L[j])) continue;
    let d = 0, k = j;
    for (; k < L.length; k++) {
      d += (L[k].match(/{/g) || []).length - (L[k].match(/}/g) || []).length;
      if (d <= 0) break;
    }
    const n = k - i + 1;
    if (n > 20) res.push([n, f.replace(/\\/g, '/').split('backend/src/')[1], i + 1, l.trim().slice(0, 70)]);
  }
}
res.sort((a, b) => b[0] - a[0]);
res.forEach(r => console.log(r.join(' | ')));
console.log('metodos >20 lineas:', res.length);

